pub type Matrix<T> = Vec<Vec<T>>;

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(shape.len() == 2, "shape must have length 2");
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    assert!(r > 0 && c > 0, "shape entries must be positive");
    assert!(!a.is_empty(), "input array must have positive length");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must equal either R or C for broadcasting"
    );

    let mut out = vec![vec![0i8; c]; r];

    if n == r {
        // Column vector broadcast across columns: out[i][j] = a[i]
        for i in 0..r {
            let v = a[i];
            for j in 0..c {
                out[i][j] = v;
            }
        }
    } else {
        // Row vector broadcast across rows: out[i][j] = a[j]
        for i in 0..r {
            out[i].copy_from_slice(&a);
        }
    }

    out
}